\\\\"eslint-plugin-react-hooks\\\\\\\": \\\\\\\"^7.1.1\\\\\\\",\\\\n    \\\\\\\"eslint-plugin-react-refresh\\\\\\\": \\\\\\\"^0.5.3\\\\\\\",\\\\n    \\\\\\\"globals\\\\\\\": \\\\\\\"^17.7.0\\\\\\\",\\\\n    \\\\\\\"jsdom\\\\\\\": \\\\\\\"^29.1.1\\\\\\\",\\\\n    \\\\\\\"typescript\\\\\\\": \\\\\\\"~6.0.2\\\\\\\",\\\\n    \\\\\\\"typescript-eslint\\\\\\\": \\\\\\\"^8.62.1\\\\\\\",\\\\n    \\\\\\\"vite\\\\\\\": \\\\\\\"^8.1.1\\\\\\\",\\\\n    \\\\\\\"vitest\\\\\\\": \\\\\\\"^4.1.9\\\\\\\"\\\\n  },\\\\n  \\\\\\\"dependencies\\\\\\\": {\\\\n    \\\\\\\"@aptabase/web\\\\\\\": \\\\\\\"^0.5.0\\\\\\\",\\\\n    \\\\\\\"@dnd-kit/core\\\\\\\": \\\\\\\"^6.3.1\\\\\\\",\\\\n    \\\\\\\"@dnd-kit/sortable\\\\\\\": \\\\\\\"^10.0.0\\\\\\\",\\\\n    \\\\\\\"@emotion/react\\\\\\\": \\\\\\\"^11.14.0\\\\\\\",\\\\n    \\\\\\\"@emotion/styled\\\\\\\": \\\\\\\"^11.14.1\\\\\\\",\\\\n    \\\\\\\"@lexical/history\\\\\\\": \\\\\\\"^0.35.0\\\\\\\",\\\\n    \\\\\\\"@lexical/link\\\\\\\": \\\\\\\"^0.35.0\\\\\\\",\\\\n    \\\\\\\"@lexical/react\\\\\\\": \\\\\\\"^0.35.0\\\\\\\",\\\\n    \\\\\\\"@mdxeditor/editor\\\\\\\": \\\\\\\"^4.0.4\\\\\\\",\\\\n    \\\\\\\"@mui/icons-material\\\\\\\": \\\\\\\"^9.2.0\\\\\\\",\\\\n    \\\\\\\"@mui/material\\\\\\\": \\\\\\\"^9.2.0\\\\\\\",\\\\n    \\\\\\\"@sentry/react\\\\\\\": \\\\\\\"^10.63.0\\\\\\\",\\\\n    \\\\\\\"lexical\\\\\\\": \\\\\\\"^0.35.0\\\\\\\",\\\\n    \\\\\\\"mdi-material-ui\\\\\\\": \\\\\\\"^8.0.0\\\\\\\",\\\\n    \\\\\\\"prismjs\\\\\\\": \\\\\\\"^1.30.0\\\\\\\",\\\\n    \\\\\\\"qrcode\\\\\\\": \\\\\\\"^1.5.4\\\\\\\",\\\\n    \\\\\\\"react\\\\\\\": \\\\\\\"^19.2.7\\\\\\\",\\\\n    \\\\\\\"react-arborist\\\\\\\": \\\\\\\"^3.13.2\\\\\\\",\\\\n    \\\\\\\"react-diff-viewer-continued\\\\\\\": \\\\\\\"^4.2.2\\\\\\\",\\\\n    \\\\\\\"react-dom\\\\\\\": \\\\\\\"^19.2.7\\\\\\\",\\\\n    \\\\\\\"react-markdown\\\\\\\": \\\\\\\"^10.1.0\\\\\\\",\\\\n    \\\\\\\"remark-gfm\\\\\\\": \\\\\\\"^4.0.1\\\\\\\",\\\\n    \\\\\\\"uuid\\\\\\\": \\\\\\\"^14.0.1\\\\\\\"\