import type { CommitReference, DiffResult, OpenInEditorRequest } from '../../data/electron_action_bridge'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import { resolveProjectConfigPaths } from '../../data/data_types'
import { configService } from '../config/config_service'

export type DiffCommitReference = Pick<CommitReference, 'branch' | 'commit' | 'filePaths'>

/**
 * Render one referenced commit through the configured Electron command.
 */
export async function generateDiff(commitReference: DiffCommitReference): Promise<DiffResult> {
    const bridge = getElectronActionBridge()
    if (!bridge) throw new Error('Diff view requires Electron local mode')

    const { branch, commit, filePaths } = commitReference
    const template = configService.get('project.diffCommand')
    const { projectFolder, releasesFolder } = resolveProjectConfigPaths(configService.getProjectConfig())

    return bridge.generateDiff({ branch, commit, filePath: filePaths[0] ?? '', projectFolder, releasesFolder, template })
}

/** Open configured external editor at file and line clicked in diff view. */
export async function openDiffLine(request: OpenInEditorRequest): Promise<void> {
    const bridge = getElectronActionBridge()
    if (!bridge) throw new Error('Opening local files requires Electron local mode')

    await bridge.openInEditor(request)
}

import { beforeEach, describe, expect, it, vi } from 'vitest'
import type { CommitReference } from '../../data/electron_action_bridge'

const generateDiffBridge = vi.fn()

vi.mock('../../data/electron_action_bridge', () => ({getElectronActionBridge: () => ({ generateDiff: generateDiffBridge })}))

vi.mock('../config/config_service', () => ({
    configService: {
        get: () => 'git show {{commit}}',
        getProjectConfig: () => ({
            actionsFolder: 'actions', archivedFolder: 'archived', projectFolder: 'design',
            releasesFolder: 'delivery/releases', workingFolder: 'feature_descriptions',
        }),
    },
}))

const { generateDiff } = await import('./diff_service')

const commitReference: CommitReference = {
    actionId: 'action-1', actionName: 'Implement', branch: 'topic', commit: 'abc123456789',
    committedAt: '2026-07-15T10:00:00+00:00', deletions: 0, filePaths: ['app/a.ts'], filesChanged: 1,
    insertions: 1, repositoryRoot: 'C:/worktree',
}

describe('generateDiff', () => {
    beforeEach(() => generateDiffBridge.mockReset())

    it('requests diff using selected commit reference metadata', async () => {
        generateDiffBridge.mockResolvedValue({ commit: commitReference.commit, files: [] })

        await generateDiff(commitReference)

        expect(generateDiffBridge).toHaveBeenCalledWith({
            branch: 'topic', commit: 'abc123456789', filePath: 'app/a.ts',
            projectFolder: 'design',
            releasesFolder: 'design/delivery/releases',
            template: 'git show {{commit}}',
        })
    })
})

