        const filePath = decoded.replace(FILE_URL_PATTERN, '');

        return filePath.startsWith('/') && /^[a-z]:[\\/]/iu.test(filePath.slice(1)) ? filePath.slice(1) : filePath;
    } catch {
        throw new Error(`Invalid local file link: ${value}`);
    }
