        runner.subscribe(laterListener);

        await expect(runToCompletion(runner)).resolves.toMatchObject({ status: 'completed' });
        expect(laterListener).toHaveBeenCalled();
        expect(errorReporter).toHaveBeenCalledWith(listenerError);
